-- Push notifications: game starting, your turn, set Away.
--
-- push_tokens: one row per device that turned notifications on. Web: the
-- browser's push subscription (endpoint + keys). Android/iPhone: an FCM token.
-- Phones write them only through save_push_token / remove_push_token (a device
-- that signs in as someone else moves to that account). The `table` function
-- reads them with the service role.
--
-- VAPID keys (Web Push) are generated by the `table` function on first use and
-- kept in Vault: the private key only the service role can read, the public
-- key is handed to browsers.

create table if not exists public.push_tokens (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  platform text not null check (platform in ('web', 'android', 'ios')),
  token text not null unique,
  subscription jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists push_tokens_user_id_idx on public.push_tokens (user_id);
alter table public.push_tokens enable row level security;
drop policy if exists "Read own push tokens" on public.push_tokens;
create policy "Read own push tokens" on public.push_tokens for select using (auth.uid() = user_id);

create or replace function public.save_push_token(p_platform text, p_token text, p_subscription jsonb default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if p_platform not in ('web', 'android', 'ios') or coalesce(length(p_token), 0) not between 10 and 2000 then
    raise exception 'bad push token';
  end if;
  insert into public.push_tokens (user_id, platform, token, subscription)
  values (auth.uid(), p_platform, p_token, p_subscription)
  on conflict (token) do update
    set user_id = excluded.user_id, platform = excluded.platform,
        subscription = excluded.subscription, updated_at = now();
end $$;
revoke execute on function public.save_push_token(text, text, jsonb) from public, anon;
grant execute on function public.save_push_token(text, text, jsonb) to authenticated;

create or replace function public.remove_push_token(p_token text)
returns void
language sql
security definer
set search_path = ''
as $$
  delete from public.push_tokens where token = p_token and user_id = auth.uid()
$$;
revoke execute on function public.remove_push_token(text) from public, anon;
grant execute on function public.remove_push_token(text) to authenticated;

-- VAPID keys, for the `table` function only
create or replace function public.push_vapid_keys()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select decrypted_secret from vault.decrypted_secrets where name = 'push_vapid_jwk'
$$;
revoke execute on function public.push_vapid_keys() from public, anon, authenticated;
grant execute on function public.push_vapid_keys() to service_role;

-- Stores the generated key pair once; a second caller gets the first one's keys
create or replace function public.push_set_vapid_keys(p_jwk text)
returns text
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform pg_advisory_xact_lock(hashtext('push_vapid_jwk'));
  if not exists (select 1 from vault.secrets where name = 'push_vapid_jwk') then
    perform vault.create_secret(p_jwk, 'push_vapid_jwk', 'Web Push (VAPID) key pair, JWK. Made by the table function.');
  end if;
  return (select decrypted_secret from vault.decrypted_secrets where name = 'push_vapid_jwk');
end $$;
revoke execute on function public.push_set_vapid_keys(text) from public, anon, authenticated;
grant execute on function public.push_set_vapid_keys(text) to service_role;
